<script setup lang="ts">
// 统计分布列表：场景 / 模型 / 凭据 / 引用类型 / 工具共用的排名 + 比例条展示。
// 个人统计页与管理统计页共用，避免「排名怎么算、占比怎么画」的规则在两处漂移。
import { computed } from "vue";
import type { AiStatsBucket } from "@/types/ai-stats";
import { fmtCount } from "@/views/ai/ai-stats-common";

const props = defineProps<{
  title: string;
  rows: AiStatsBucket[];
  /** 按哪个指标排名与画比例条 */
  metric: "conversations" | "messages" | "total_tokens";
  /** key → 展示名（场景/引用类型传映射，模型/工具不传则原样展示） */
  labels?: Record<string, string>;
  emptyText?: string;
}>();

const metricText: Record<string, string> = {
  conversations: "会话",
  messages: "消息",
  total_tokens: "tokens",
};

const maxValue = computed(() => {
  const values = props.rows.map((row) => row[props.metric]);
  return Math.max(0, ...values);
});

const valueOf = (row: AiStatsBucket): number => row[props.metric];

const pctOf = (row: AiStatsBucket): number => {
  if (maxValue.value <= 0) {
    return 0;
  }
  return Math.max(1, Math.round((valueOf(row) / maxValue.value) * 100));
};
</script>

<template>
  <div class="dist-block">
    <div class="dist-title">{{ title }}</div>
    <div v-if="rows.length === 0" class="dist-empty">{{ emptyText ?? "暂无数据" }}</div>
    <div v-for="row in rows" :key="row.key" class="dist-row">
      <div class="dist-row-head">
        <span class="dist-label" :title="labels?.[row.key] ?? row.key">{{ labels?.[row.key] ?? row.key }}</span>
        <span class="dist-value">
          {{ fmtCount(valueOf(row)) }}<span class="dist-metric">{{ metricText[metric] }}</span>
        </span>
      </div>
      <t-progress
        :percentage="pctOf(row)"
        :color="'#0052d9'"
        :track-color="'var(--td-bg-color-component)'"
        size="small"
      />
    </div>
  </div>
</template>

