// AI 教练统计页的共享展示辅助（个人统计页与管理统计页共用）。
//
// 只放「纯展示」逻辑：数量/文案格式化、场景与引用类型的展示名、echarts option 构建。
// 数据来源仍然只有 apis/ai-stats.ts 一处，抽出来是为了避免两个统计页各写一份、日后展示规则漂移。

import type { EChartsOption } from "@/util/echarts";
import type { AiSceneMeta } from "@/apis/ai-conversation.ts";
import { GetAiCoachPageTitle } from "@/stores/aiCoachEntry.ts";

// 图表色板（与 tdesign 品牌色系一致的固定色，canvas 不认识 CSS 变量）
export const AI_STATS_PALETTE = [
  "#0052d9",
  "#00a870",
  "#ed7b2f",
  "#e34d59",
  "#834ec2",
  "#00a0e9",
  "#5a6672",
  "#f2bd27",
  "#2ba471",
  "#9e8bd8",
];

// token / 消息数量格式化：千分位 + K/M 缩写（BYOK 用户对成本敏感，数字要一眼可读）
export function fmtCount(n: number): string {
  if (n < 1000) {
    return String(n);
  }
  if (n < 1_000_000) {
    const v = n / 1000;
    return `${v >= 100 ? v.toFixed(0) : v.toFixed(1)}K`;
  }
  const v = n / 1_000_000;
  return `${v >= 100 ? v.toFixed(0) : v.toFixed(1)}M`;
}

/** 场景展示名：以 /ai/scene 的服务端文案为准，取不到时回退场景 key */
export function getSceneTitle(sceneList: AiSceneMeta[], key: string): string {
  return sceneList.find((meta) => meta.key === key)?.title ?? key;
}

/** 引用类型展示名：judge → 提交、problem → 题目、contest → 比赛；空串 → 自由对话 */
export function getRefTypeTitle(key: string): string {
  if (!key) {
    return "自由对话";
  }
  const map: Record<string, string> = {
    judge: "提交",
    problem: "题目",
    contest: "比赛",
  };
  return map[key] ?? key;
}

/** 打开页面展示名：路由 name → 中文（来自页面入口注册表的静态映射）；空串 → 未知页面（旧数据） */
export function getEntryPageTitle(key: string): string {
  if (!key) {
    return "未知页面";
  }
  return GetAiCoachPageTitle(key);
}

/** 折线趋势图（近 30 天）：左轴数量（会话/消息/活跃用户），右轴 token */
export function buildTrendOption(
  dates: string[],
  countSeries: { name: string; data: number[]; color?: string }[],
  tokenSeries: { name: string; data: number[]; color?: string }[],
): EChartsOption {
  return {
    tooltip: { trigger: "axis" },
    legend: { top: 0, type: "scroll", textStyle: { fontSize: 12 } },
    grid: { left: 8, right: 8, top: 40, bottom: 8, containLabel: true },
    xAxis: {
      type: "category",
      boundaryGap: false,
      data: dates,
      axisLabel: { fontSize: 11 },
      axisTick: { show: false },
    },
    yAxis: [
      { type: "value", name: "数量", minInterval: 1, splitLine: { lineStyle: { opacity: 0.4 } } },
      { type: "value", name: "tokens", splitLine: { show: false } },
    ],
    series: [
      ...countSeries.map((s) => ({
        name: s.name,
        type: "line" as const,
        smooth: true,
        symbol: "none",
        yAxisIndex: 0,
        data: s.data,
        ...(s.color ? { lineStyle: { color: s.color }, itemStyle: { color: s.color } } : {}),
      })),
      ...tokenSeries.map((s) => ({
        name: s.name,
        type: "line" as const,
        smooth: true,
        symbol: "none",
        yAxisIndex: 1,
        data: s.data,
        ...(s.color ? { lineStyle: { color: s.color }, itemStyle: { color: s.color } } : {}),
      })),
    ],
  };
}

/** 分布饼图（场景 / 引用类型等按会话数占比） */
export function buildPieOption(data: { name: string; value: number }[]): EChartsOption {
  return {
    tooltip: { trigger: "item", formatter: "{b}: {c}（{d}%）" },
    legend: { bottom: 0, type: "scroll", textStyle: { fontSize: 12 } },
    color: AI_STATS_PALETTE,
    series: [
      {
        type: "pie",
        radius: ["38%", "64%"],
        center: ["50%", "46%"],
        itemStyle: { borderWidth: 2, borderColor: "transparent" },
        label: { show: false },
        data,
      },
    ],
  };
}
